const wf = $json || {};
const nodes = Array.isArray(wf.nodes) ? wf.nodes : [];
function getPrompt(n) {
  const p = (n && n.parameters) || {};
  if (p.options && typeof p.options.systemMessage === 'string') return p.options.systemMessage;
  if (typeof p.systemMessage === 'string') return p.systemMessage;
  if (typeof p.text === 'string') return p.text;
  return '';
}
let agentNode = nodes.find(n => n && n.name === 'Builder Agent');
if (!agentNode) agentNode = nodes.find(n => n && typeof n.type === 'string' && n.type.indexOf('langchain.agent') !== -1);
if (!agentNode) agentNode = nodes.find(n => getPrompt(n).length > 0);
const prompt = agentNode ? getPrompt(agentNode) : '';
const labelMap = {};
const labelRe = /\*\*([^*(]+?)\s*\(`([A-Za-z0-9]{16})`\)\*\*/g;
let lm;
while ((lm = labelRe.exec(prompt)) !== null) { if (!labelMap[lm[2]]) labelMap[lm[2]] = lm[1].trim(); }
const allIds = [];
const idRe = /`([A-Za-z0-9]{16})`/g;
let im;
while ((im = idRe.exec(prompt)) !== null) { if (allIds.indexOf(im[1]) === -1) allIds.push(im[1]); }
const refs = allIds.map(id => ({ id, label: labelMap[id] || null }));
return [{ json: { prompt, refs, ref_count: refs.length } }];

const refs = ($('Extract Prompt & IDs').first().json.refs) || [];
const wfResp = $('List All Workflows').first().json || {};
const wfList = Array.isArray(wfResp.data) ? wfResp.data : (Array.isArray(wfResp) ? wfResp : []);
const wfById = {};
for (const w of wfList) { if (w && w.id) wfById[w.id] = w; }
const KNOWN_TABLES = {
  'lxbB2v0RHaAAVH6E': 'Darwin Sessions',
  'G3P55vPsJtpt1pk5': 'Darwin Evals',
  'bVLPI1lsi9GsAaQc': 'Darwin Eval Results',
  'tzlHlDXi6x6rqJ5W': 'Sync Session State',
  'eTTy7a2k7jQdE6ts': 'Sync Project State'
};
const EXPECTED_INACTIVE = ['sJaqeSayRPznbd9h'];
function norm(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]/g, ''); }
const passed = [], failed = [], warnings = [];
for (const ref of refs) {
  const id = ref.id; const label = ref.label;
  if (wfById[id]) {
    const w = wfById[id];
    const isActive = w.active === true;
    const expectedInactive = EXPECTED_INACTIVE.indexOf(id) !== -1;
    const rec = { id, label, kind: 'workflow', exists: true, name: w.name || null, active: isActive };
    if (!isActive && !expectedInactive) { failed.push(Object.assign({ reason: 'inactive' }, rec)); }
    else { passed.push(rec); }
    if (label && w.name && norm(label) !== norm(w.name) && norm(w.name).indexOf(norm(label)) === -1 && norm(label).indexOf(norm(w.name)) === -1) {
      warnings.push({ id, label, kind: 'workflow', actualName: w.name });
    }
  } else if (KNOWN_TABLES[id]) {
    passed.push({ id, label, kind: 'dataTable', exists: true, name: KNOWN_TABLES[id], active: null });
  } else {
    failed.push({ id, label, kind: 'unknown', exists: false, name: null, active: null, reason: 'missing' });
  }
}
return [{ json: { passed, failed, warnings, pass_count: passed.length, fail_count: failed.length, warn_count: warnings.length } }];

const validation = $json || {};
const failed = Array.isArray(validation.failed) ? validation.failed : [];
const wfResp = $('List All Workflows').first().json || {};
const wfList = Array.isArray(wfResp.data) ? wfResp.data : (Array.isArray(wfResp) ? wfResp : []);
function norm(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]/g, ''); }
const fixes = []; const unfixable = [];
for (const f of failed) {
  if (f.reason !== 'missing') { unfixable.push(f); continue; }
  if (!f.label) { unfixable.push(f); continue; }
  const target = norm(f.label);
  let matches = wfList.filter(w => w && w.name && norm(w.name) === target);
  if (matches.length === 0) { matches = wfList.filter(w => w && w.name && (norm(w.name).indexOf(target) !== -1 || target.indexOf(norm(w.name)) !== -1)); }
  if (matches.length === 1) { fixes.push({ oldId: f.id, newId: matches[0].id, label: f.label, matchedName: matches[0].name }); }
  else { unfixable.push(f); }
}
return [{ json: { fixes, unfixable, fix_count: fixes.length, unfixable_count: unfixable.length } }];

const fixes = ($json.fixes) || [];
const wf = $('Fetch Builder Workflow').first().json || {};
const nodes = Array.isArray(wf.nodes) ? JSON.parse(JSON.stringify(wf.nodes)) : [];
function getPromptField(n) {
  const p = (n && n.parameters) || {};
  if (p.options && typeof p.options.systemMessage === 'string') return 'options.systemMessage';
  if (typeof p.systemMessage === 'string') return 'systemMessage';
  if (typeof p.text === 'string') return 'text';
  return null;
}
let idx = nodes.findIndex(n => n && n.name === 'Builder Agent');
if (idx === -1) idx = nodes.findIndex(n => n && typeof n.type === 'string' && n.type.indexOf('langchain.agent') !== -1);
if (idx === -1) idx = nodes.findIndex(n => getPromptField(n) !== null);
const agent = nodes[idx];
const field = getPromptField(agent);
let prompt = field === 'options.systemMessage' ? agent.parameters.options.systemMessage : agent.parameters[field];
for (const fx of fixes) { prompt = prompt.split(fx.oldId).join(fx.newId); }
if (field === 'options.systemMessage') { agent.parameters.options.systemMessage = prompt; } else { agent.parameters[field] = prompt; }
nodes[idx] = agent;
const body = { name: wf.name, nodes: nodes, connections: wf.connections, settings: wf.settings || {} };
return [{ json: { updateBody: body, applied_fixes: fixes } }];

const validation = $('Validate IDs').first().json || {};
const fixData = $('Compute Auto-Fixes').first().json || {};
const date = new Date().toISOString().slice(0, 10);
const passed = validation.passed || []; const warnings = validation.warnings || [];
const fixes = fixData.fixes || []; const unfixable = fixData.unfixable || [];
const lines = [];
lines.push(':hospital: *Health Check Report* — ' + date);
lines.push('');
if (fixes.length) {
  lines.push(':wrench: *Prepared ' + fixes.length + ' auto-fix(es):*');
  for (const fx of fixes) { lines.push('• ' + (fx.label || 'unlabelled') + ': `' + fx.oldId + '` -> `' + fx.newId + '` (' + fx.matchedName + ')'); }
  lines.push('_:warning: Auto-write node is disabled by default. Enable "Apply Fix (PUT)" to persist; changes require manual publish._');
  lines.push('');
}
if (unfixable.length) {
  lines.push(':red_circle: *' + unfixable.length + ' ID(s) could not be resolved:*');
  for (const u of unfixable) { lines.push('• `' + u.id + '` (' + (u.label || 'unlabelled') + ') — ' + (u.reason === 'inactive' ? 'workflow exists but is INACTIVE' : 'not found in any workflow or known data table')); }
  lines.push('');
}
if (warnings.length) {
  lines.push(':warning: *' + warnings.length + ' name mismatch(es):*');
  for (const w of warnings) { lines.push('• `' + w.id + '`: prompt says "' + w.label + '", actual name is "' + w.actualName + '"'); }
  lines.push('');
}
lines.push('*Summary:* ' + passed.length + ' passed, ' + fixes.length + ' auto-fixed (prepared), ' + unfixable.length + ' failed, ' + warnings.length + ' warnings');
return [{ json: { message: lines.join('\n') } }];

const validation = $('Validate IDs').first().json || {};
const fixData = $('Compute Auto-Fixes').first().json || {};
const date = new Date().toISOString().slice(0, 10);
const passed = validation.passed || []; const warnings = validation.warnings || [];
const unfixable = fixData.unfixable || [];
const lines = [];
lines.push(':hospital: *Health Check Report* — ' + date);
lines.push('');
if (unfixable.length === 0 && warnings.length === 0) {
  lines.push(':white_check_mark: All ' + passed.length + ' referenced IDs validated successfully. No issues found.');
  lines.push('');
}
if (unfixable.length) {
  lines.push(':red_circle: *' + unfixable.length + ' ID(s) could not be resolved:*');
  for (const u of unfixable) { lines.push('• `' + u.id + '` (' + (u.label || 'unlabelled') + ') — ' + (u.reason === 'inactive' ? 'workflow exists but is INACTIVE' : 'not found in any workflow or known data table')); }
  lines.push('');
}
if (warnings.length) {
  lines.push(':warning: *' + warnings.length + ' name mismatch(es):*');
  for (const w of warnings) { lines.push('• `' + w.id + '`: prompt says "' + w.label + '", actual name is "' + w.actualName + '"'); }
  lines.push('');
}
lines.push('*Summary:* ' + passed.length + ' passed, 0 auto-fixed, ' + unfixable.length + ' failed, ' + warnings.length + ' warnings');
return [{ json: { message: lines.join('\n') } }];
